export type JsonSchema =
  | boolean
  | {
      [key: string]: unknown;
      type?: string | string[];
      properties?: Record<string, JsonSchema>;
      required?: string[];
      enum?: unknown[];
      description?: string;
      title?: string;
      items?: JsonSchema;
    };
export interface ToolDefinition {
  name: string;
  title?: string;
  description?: string;
  inputSchema: JsonSchema;
  annotations?: {
    readOnlyHint?: boolean;
    destructiveHint?: boolean;
    untrustedContentHint?: boolean;
    consequentialHint?: boolean;
    [key: string]: unknown;
  };
}
export interface Execution {
  id: string;
  name: string;
  source: "human" | "agent" | "simulator";
  status: "running" | "success" | "error" | "cancelled";
  startedAt: number;
  completedAt?: number;
  args: Record<string, unknown>;
  result?: unknown;
  error?: string;
  progress?: { progress: number; total?: number; message?: string };
}
export type Support = "checking" | "native" | "legacy" | "unsupported";
export interface ToolContext {
  signal: AbortSignal;
  source: Execution["source"];
}
export interface WebTool extends ToolDefinition {
  execute: (
    args: Record<string, unknown>,
    context: ToolContext,
  ) => unknown | Promise<unknown>;
}
export function errorMessage(error: unknown) {
  return error instanceof Error ? error.message : "The operation failed.";
}

import Ajv2020 from "ajv/dist/2020.js";
import addFormats from "ajv-formats";
import type { JsonSchema } from "@/lib/mcp/types";
const ajv = new Ajv2020({
  allErrors: true,
  strict: false,
  validateFormats: true,
  validateSchema: true,
});
addFormats(ajv);
export function validateArguments(
  schema: JsonSchema,
  value: unknown,
): string | null {
  try {
    const validate = ajv.compile(schema);
    if (validate(value)) return null;
    return (validate.errors ?? [])
      .map((e) => `${e.instancePath || "Input"} ${e.message}`)
      .join("; ");
  } catch {
    return "This schema cannot be validated locally. Provide a self-contained JSON Schema 2020-12 without external references.";
  }
}
export function simpleFields(
  schema: JsonSchema,
): schema is Exclude<JsonSchema, boolean> {
  if (
    !schema ||
    typeof schema !== "object" ||
    Array.isArray(schema) ||
    schema.type !== "object"
  )
    return false;
  if (
    schema.properties &&
    (typeof schema.properties !== "object" || Array.isArray(schema.properties))
  )
    return false;
  if (
    Object.keys(schema).some((k) =>
      [
        "$ref",
        "allOf",
        "anyOf",
        "oneOf",
        "if",
        "dependentSchemas",
        "patternProperties",
      ].includes(k),
    )
  )
    return false;
  return Object.values(schema.properties ?? {}).every(
    (p) =>
      p !== null &&
      typeof p === "object" &&
      !Array.isArray(p) &&
      ["string", "number", "integer", "boolean"].includes(String(p.type)) &&
      !p.$ref &&
      !p.anyOf &&
      !p.oneOf &&
      !p.allOf,
  );
}

"use client";
import { useId, useState } from "react";
import {
  Button,
  Input,
  Label,
  NativeCheckbox,
  NativeSelect,
  Textarea,
} from "@fabrials/ui";
import { simpleFields, validateArguments } from "@/lib/mcp/schema";
import { errorMessage, type JsonSchema } from "@/lib/mcp/types";
export function ArgumentsForm({
  schema,
  onSubmit,
  submitLabel = "Run tool",
  disabled = false,
  initialValues = {},
}: {
  schema: JsonSchema;
  onSubmit: (args: Record<string, unknown>) => unknown | Promise<unknown>;
  submitLabel?: string;
  disabled?: boolean;
  initialValues?: Record<string, unknown>;
}) {
  const id = useId();
  const [error, setError] = useState("");
  const [pending, setPending] = useState(false);
  const fields = simpleFields(schema) ? (schema.properties ?? {}) : null;
  const [json, setJson] = useState(JSON.stringify(initialValues, null, 2));
  return (
    <form
      className="space-y-4"
      onSubmit={async (event) => {
        event.preventDefault();
        if (pending || disabled) return;
        const data = new FormData(event.currentTarget);
        setError("");
        try {
          let args: Record<string, unknown>;
          if (!fields) args = JSON.parse(json);
          else {
            args = {};
            for (const [name, field] of Object.entries(fields)) {
              if (typeof field === "boolean") continue;
              const raw = data.get(name);
              const required =
                typeof schema !== "boolean" && schema.required?.includes(name);
              if (field.type === "boolean") {
                args[name] = field.enum ? raw === "true" : raw === "on";
                continue;
              }
              if (raw === "" && !required) continue;
              args[name] =
                field.type === "number" || field.type === "integer"
                  ? Number(raw)
                  : String(raw ?? "");
            }
          }
          if (!args || typeof args !== "object" || Array.isArray(args))
            throw new Error("Arguments must be a JSON object.");
          const invalid = validateArguments(schema, args);
          if (invalid) throw new Error(invalid);
          setPending(true);
          await onSubmit(args);
        } catch (e) {
          setError(errorMessage(e));
        } finally {
          setPending(false);
        }
      }}
    >
      {fields ? (
        Object.entries(fields).map(([name, field]) => {
          if (typeof field === "boolean") return null;
          const required =
            typeof schema !== "boolean" && schema.required?.includes(name);
          const fieldId = `${id}-${name}`;
          return (
            <div className="space-y-1.5" key={name}>
              <Label htmlFor={fieldId}>
                {field.title ?? name}
                {required && (
                  <span aria-label="required" className="text-muted-foreground">
                    *
                  </span>
                )}
              </Label>
              {field.enum ? (
                <NativeSelect
                  id={fieldId}
                  name={name}
                  required={required}
                  defaultValue={String(
                    initialValues[name] ?? field.default ?? "",
                  )}
                  disabled={pending || disabled}
                >
                  <option value="">Select…</option>
                  {field.enum.map((value, index) => (
                    <option key={index} value={String(value)}>
                      {String(value)}
                    </option>
                  ))}
                </NativeSelect>
              ) : field.type === "boolean" ? (
                <NativeCheckbox
                  id={fieldId}
                  name={name}
                  defaultChecked={Boolean(initialValues[name] ?? field.default)}
                  disabled={pending || disabled}
                />
              ) : (
                <Input
                  id={fieldId}
                  name={name}
                  type={
                    ["integer", "number"].includes(String(field.type))
                      ? "number"
                      : field.format === "date"
                        ? "date"
                        : field.format === "email"
                          ? "email"
                          : "text"
                  }
                  step={field.type === "integer" ? 1 : "any"}
                  min={
                    typeof field.minimum === "number"
                      ? field.minimum
                      : undefined
                  }
                  max={
                    typeof field.maximum === "number"
                      ? field.maximum
                      : undefined
                  }
                  required={required}
                  defaultValue={String(
                    initialValues[name] ?? field.default ?? "",
                  )}
                  disabled={pending || disabled}
                  aria-describedby={
                    field.description ? `${fieldId}-help` : undefined
                  }
                />
              )}
              {field.description && (
                <p
                  id={`${fieldId}-help`}
                  className="text-xs text-muted-foreground"
                >
                  {field.description}
                </p>
              )}
            </div>
          );
        })
      ) : (
        <div className="space-y-2">
          <Label htmlFor={id}>Arguments · JSON</Label>
          <Textarea
            id={id}
            value={json}
            onChange={(e) => setJson(e.target.value)}
            rows={8}
            spellCheck={false}
            className="font-mono text-xs"
            disabled={pending || disabled}
          />
          <p className="text-xs text-muted-foreground">
            This schema uses advanced JSON Schema features. Edit its arguments
            directly.
          </p>
        </div>
      )}
      {error && (
        <p role="alert" className="text-sm text-destructive">
          {error}
        </p>
      )}
      <Button type="submit" disabled={disabled || pending} aria-busy={pending}>
        {pending ? "Running…" : submitLabel}
      </Button>
    </form>
  );
}

"use client";
import { useState } from "react";
import { Button } from "@fabrials/ui";
import { cn } from "@/lib/utils";
export function safeUrl(value: unknown): string | undefined {
  if (typeof value !== "string") return;
  try {
    const url = new URL(value);
    return ["https:", "http:"].includes(url.protocol) ? url.href : undefined;
  } catch {
    return;
  }
}
function Json({ value }: { value: unknown }) {
  return (
    <pre className="max-h-96 overflow-auto whitespace-pre-wrap break-words rounded-lg bg-muted/70 p-4 font-mono text-xs leading-relaxed">
      {JSON.stringify(value, null, 2) ?? String(value)}
    </pre>
  );
}
function Content({ value }: { value: unknown }) {
  if (!value || typeof value !== "object") return <Json value={value} />;
  const block = value as Record<string, unknown>;
  if (block.type === "text" && typeof block.text === "string")
    return (
      <p className="whitespace-pre-wrap break-words text-sm leading-relaxed">
        {block.text}
      </p>
    );
  if (block.type === "resource_link" && safeUrl(block.uri))
    return (
      <a
        className="text-sm underline underline-offset-4"
        href={safeUrl(block.uri)}
        target="_blank"
        rel="noopener noreferrer"
      >
        {String(block.name ?? block.uri)}
      </a>
    );
  if (
    block.type === "resource" &&
    block.resource &&
    typeof block.resource === "object"
  ) {
    const resource = block.resource as Record<string, unknown>;
    return typeof resource.text === "string" ? (
      <pre className="max-h-80 overflow-auto whitespace-pre-wrap text-xs">
        {resource.text}
      </pre>
    ) : (
      <Json value={resource} />
    );
  }
  if (
    typeof block.data === "string" &&
    block.data.length <= 8_000_000 &&
    typeof block.mimeType === "string"
  ) {
    const src = `data:${block.mimeType};base64,${block.data}`;
    // Only inert raster formats are embedded; remote URLs and SVG are never executed.
    if (
      block.type === "image" &&
      /^image\/(png|jpeg|webp|gif)$/.test(block.mimeType)
    )
      return (
        <picture>
          <img
            src={src}
            alt="Tool result"
            className="max-h-80 max-w-full rounded-md object-contain"
          />
        </picture>
      );
    if (
      block.type === "audio" &&
      /^audio\/(mpeg|mp3|wav|ogg|webm)$/.test(block.mimeType)
    )
      return <audio controls src={src} aria-label="Tool audio result" />;
  }
  return <Json value={value} />;
}
export function ResultView({
  result,
  className,
}: {
  result: unknown;
  className?: string;
}) {
  const [raw, setRaw] = useState(false);
  const object =
    result && typeof result === "object"
      ? (result as Record<string, unknown>)
      : undefined;
  const content = Array.isArray(object?.content)
    ? object.content
    : Array.isArray(object?.contents)
      ? object.contents
      : null;
  return (
    <div className={cn("space-y-3", className)}>
      <div className="flex items-center justify-between">
        <span className="text-xs font-medium text-muted-foreground">
          Result
        </span>
        <Button
          variant="ghost"
          size="xs"
          onClick={() => setRaw(!raw)}
          aria-pressed={raw}
        >
          {raw ? "Preview" : "Raw JSON"}
        </Button>
      </div>
      {raw ? (
        <Json value={result} />
      ) : (
        <>
          {content?.map((block, index) => (
            <Content key={index} value={block} />
          ))}
          {object && "structuredContent" in object ? (
            <Json value={object.structuredContent} />
          ) : (
            !content && <Json value={result} />
          )}
        </>
      )}
    </div>
  );
}

"use client";
import { useState } from "react";
import type {
  Resource,
  ResourceTemplateType,
  Prompt,
} from "@modelcontextprotocol/client";
import { Button } from "@fabrials/ui";
import { ArgumentsForm } from "@/components/webmcp/arguments-form";
import { ResultView } from "@/components/webmcp/result-view";
import { errorMessage } from "@/lib/mcp/types";
export function ResourceExplorer({
  resources,
  templates = [],
  onRead,
}: {
  resources: Resource[];
  templates?: ResourceTemplateType[];
  onRead: (uri: string) => Promise<unknown>;
}) {
  const [result, setResult] = useState<unknown>();
  const [error, setError] = useState("");
  const [pending, setPending] = useState(false);
  async function read(uri: string) {
    setError("");
    setPending(true);
    try {
      setResult(await onRead(uri));
    } catch (e) {
      setError(errorMessage(e));
    } finally {
      setPending(false);
    }
  }
  return (
    <section className="space-y-4">
      <h3 className="text-sm font-medium">Resources</h3>
      {!resources.length && (
        <p className="text-sm text-muted-foreground">
          No resources advertised.
        </p>
      )}
      {resources.map((resource) => (
        <div
          key={resource.uri}
          className="flex items-center justify-between gap-3 rounded-lg border p-3"
        >
          <div className="min-w-0">
            <p className="text-sm font-medium">
              {resource.title ?? resource.name}
            </p>
            <p className="break-all font-mono text-[10px] text-muted-foreground">
              {resource.uri}
            </p>
          </div>
          <Button
            size="xs"
            variant="outline"
            disabled={pending}
            onClick={() => void read(resource.uri)}
          >
            Read
          </Button>
        </div>
      ))}
      {templates.map((template) => (
        <details key={template.uriTemplate} className="rounded-lg border p-3">
          <summary className="cursor-pointer text-sm">
            {template.name} · template
          </summary>
          <p className="my-3 break-all font-mono text-xs text-muted-foreground">
            {template.uriTemplate}
          </p>
          <ArgumentsForm
            schema={{
              type: "object",
              properties: {
                uri: {
                  type: "string",
                  description:
                    "Enter a complete resource URI matching this template.",
                },
              },
              required: ["uri"],
            }}
            submitLabel="Read resource"
            onSubmit={(args) => read(String(args.uri))}
          />
        </details>
      ))}
      {error && (
        <p role="alert" className="text-sm text-destructive">
          {error}
        </p>
      )}
      {result !== undefined && <ResultView result={result} />}
    </section>
  );
}
export function PromptCatalog({
  prompts,
  onGet,
}: {
  prompts: Prompt[];
  onGet: (name: string, args: Record<string, string>) => Promise<unknown>;
}) {
  const [result, setResult] = useState<unknown>();
  return (
    <section className="space-y-4">
      <h3 className="text-sm font-medium">Prompts</h3>
      {!prompts.length && (
        <p className="text-sm text-muted-foreground">No prompts advertised.</p>
      )}
      {prompts.map((prompt) => (
        <details key={prompt.name} className="rounded-lg border p-4">
          <summary className="cursor-pointer text-sm font-medium">
            {prompt.title ?? prompt.name}
          </summary>
          <p className="my-3 text-xs text-muted-foreground">
            {prompt.description}
          </p>
          <ArgumentsForm
            schema={{
              type: "object",
              properties: Object.fromEntries(
                (prompt.arguments ?? []).map((arg) => [
                  arg.name,
                  { type: "string", description: arg.description },
                ]),
              ),
              required: (prompt.arguments ?? [])
                .filter((a) => a.required)
                .map((a) => a.name),
            }}
            submitLabel="Get prompt"
            onSubmit={async (args) =>
              setResult(
                await onGet(prompt.name, args as Record<string, string>),
              )
            }
          />
        </details>
      ))}
      {result !== undefined && <ResultView result={result} />}
    </section>
  );
}
